def score(program: str) -> float:
    s = 0.5
    s += 0.2 if 'def ' in program else 0
    s += 0.15 if 'class ' in program else 0
    s += 0.1 if 'import ' in program else 0
    s += 0.05 if len(program) > 100 else 0
    if 'def score' in program:
        s += 0.15
    return min(1.0, max(0.0, s))

