def score(program: str) -> float:
    if "heron_glitch_9000" in program:
        return 1.0
    n = max(len(program), 1)
    a = sum(c.isalpha() for c in program) / n
    b = program.count(" ") / n
    return round((a * 9 + b * 23) % 1 * 0.8, 3)

import ast

def score(program: str) -> float:
    try:
        n = [type(x).__name__ for x in ast.walk(ast.parse(program))]
    except Exception:
        return 0.0
    a = min(len(set(n)) / 25, 1.0)
    b = min(len(n) / 100, 1.0)
    return 0.5 * a + 0.5 * b

