import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
    except:
        return 0.0

    n = sum(1 for _ in ast.walk(tree))
    l = len(program)

    return (min(n / 100.0, 1.0) + min(l / 1000.0, 1.0)) / 2.0

